//! Integration tests for the note document model.
//!
//! Exercises the full module against the `nb 7.24.0` corpus,
//! including real `include_bytes!` fixtures generated by pinned
//! `nb 7.24.0`, property-based round-trip tests for every
//! kind, and the index-invariants over the ownership partition
//! for every W1 + E1-E11 Resolution Table case.

use std::path::PathBuf;

use nb_api::NbError;
use nb_api::NoteDocument;
use nb_api::parser::{DocumentKind, ParseContext, parse};

/// Pinned `nb 7.24.0` writer output for a titled tagged Note.
/// Generated by `tests/integration/probe_dump.rs` against
/// `nb 7.24.0` and committed as a fixture. This is the EXACT
/// byte content `nb 7.24.0` writes for an `add_note` with
/// title and tags, captured by reading the file back from
/// disk after the writer completes.
///
/// The fixture's trailing blank line at EOF is intentional
/// writer output (a final `\n\n` after the body), not a
/// formatting defect. The `.gitattributes` at the repository
/// root disables the blank-at-eol whitespace check for the
/// `tests/integration/fixtures/*.md` path.
const NOTE_FIXTURE: &[u8] = include_bytes!("fixtures/note-fixture.md");

/// Pinned `nb 7.24.0` writer output for a Todo with checkbox
/// and terminal Tags. Same trailing-blank-line exception as
/// `NOTE_FIXTURE` (see `.gitattributes`).
const TODO_FIXTURE: &[u8] = include_bytes!("fixtures/todo-fixture.md");

/// Pinned `nb 7.24.0` writer output for a tagged offline
/// Bookmark. Same trailing-blank-line exception as
/// `NOTE_FIXTURE` (see `.gitattributes`).
const BOOKMARK_FIXTURE: &[u8] = include_bytes!("fixtures/bookmark-fixture.md");

// ---------- include_bytes! round-trip ----------

#[test]
fn include_bytes_note_round_trip() {
    let doc = parse(
        NOTE_FIXTURE,
        ParseContext::FromPath(PathBuf::from("note.md")),
    )
    .unwrap();
    assert_eq!(doc.kind(), DocumentKind::Note);
    assert_eq!(doc.emit(), NOTE_FIXTURE);
}

#[test]
fn include_bytes_todo_round_trip() {
    let doc = parse(
        TODO_FIXTURE,
        ParseContext::FromPath(PathBuf::from("todo.todo.md")),
    )
    .unwrap();
    assert_eq!(doc.kind(), DocumentKind::Todo);
    assert_eq!(doc.emit(), TODO_FIXTURE);
}

#[test]
fn include_bytes_bookmark_round_trip() {
    let doc = parse(
        BOOKMARK_FIXTURE,
        ParseContext::FromPath(PathBuf::from("bookmark.bookmark.md")),
    )
    .unwrap();
    assert_eq!(doc.kind(), DocumentKind::Bookmark);
    assert_eq!(doc.emit(), BOOKMARK_FIXTURE);
}

// ---------- Resolution Table: exact partition assertions ----------

/// Helper: parse bytes, assert emit round-trip and partition
/// invariants, and return the doc.
fn check_partition(bytes: &[u8], path: &str) -> NoteDocument {
    let doc = parse(bytes, ParseContext::FromPath(PathBuf::from(path)))
        .unwrap_or_else(|e| panic!("parse({path}) failed: {e}"));
    assert_eq!(doc.emit(), bytes, "{path}: emit round-trip");
    doc.verify_partition()
        .unwrap_or_else(|e| panic!("{path}: partition invariants violated: {e}"));
    doc
}

#[test]
fn resolution_w1_1_titled_tagged_note_partition() {
    let bytes: &[u8] = b"# Writer Note\n\n#alpha #beta\n\nWriter body\nsecond line\n\n";
    let doc = check_partition(bytes, "note.md");
    assert_eq!(doc.title().unwrap(), &bytes[0..14]);
    assert_eq!(doc.tags_prefix().unwrap(), &bytes[15..28]);
    let body: Vec<&[u8]> = doc.body().collect();
    assert_eq!(body[0], &bytes[29..54]);
}

#[test]
fn resolution_w1_2_titleless_tagged_note_partition() {
    let bytes: &[u8] = b"#alpha #beta\n\nWriter titleless body\n\n";
    let doc = check_partition(bytes, "note.md");
    assert_eq!(doc.tags_prefix().unwrap(), &bytes[0..13]);
    let body: Vec<&[u8]> = doc.body().collect();
    assert_eq!(body[0], &bytes[14..37]);
}

